
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_pbe_mol_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_pbe_mol", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.836033420242499e-02, -5.731131837517318e-02, -5.580912645434471e-02, -5.366248269461252e-02, -5.060518527658408e-02, -4.627684794795721e-02, -4.022421537178834e-02, -3.201056029910660e-02, -2.175544237121417e-02, -1.175187804802785e-02, -8.200006743773632e-03, -3.425903588776875e-02, -4.371450425860350e-02, -2.849176534493236e-02, -1.288858860488856e-02, -2.621129050722280e-03, -1.316145822363500e-04, -1.171400559702345e-06, -1.198492839654236e-09, -4.742247701568798e-14]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


